function minimumSwaps(nums) {
  let minIndex = 0;
  let maxIndex = 0;

  for (let i = 1; i < nums.length; i++) {
    if (nums[i] < nums[minIndex]) {
      minIndex = i;
    }
    if (nums[i] >= nums[maxIndex]) {
      maxIndex = i;
    }
  }

  const swaps = minIndex + (nums.length - 1 - maxIndex);
  return minIndex > maxIndex ? swaps - 1 : swaps;
}

