function minimumSwaps(nums) {
  const n = nums.length;
  const low = Math.min(...nums);
  const high = Math.max(...nums);
  let best = Infinity;
  // Try every copy of the smallest and the largest value, moving them in either order by real swaps.
  for (let a = 0; a < n; a++) {
    if (nums[a] !== low) continue;
    for (let b = 0; b < n; b++) {
      if (nums[b] !== high) continue;
      for (const minFirst of [true, false]) {
        const cards = nums.map((value, id) => ({ value, id }));
        let moves = 0;
        const bring = (id, target) => {
          let at = cards.findIndex(card => card.id === id);
          while (at !== target) {
            const step = at < target ? 1 : -1;
            [cards[at], cards[at + step]] = [cards[at + step], cards[at]];
            at += step;
            moves++;
          }
        };
        if (minFirst) { bring(a, 0); bring(b, n - 1); } else { bring(b, n - 1); bring(a, 0); }
        if (cards[0].value === low && cards[n - 1].value === high) best = Math.min(best, moves);
      }
    }
  }
  return best;
}

