    const n = 1 + Math.floor(rand() * 9);
    const spread = 1 + Math.floor(rand() * 6);
    const base = 1 + Math.floor(rand() * 5);
    return [Array.from({ length: n }, () => base + Math.floor(rand() * spread))];
  }
  const n = 1500 + Math.floor(rand() * 501);
  const spread = rand() < 0.5 ? 20 : 100000;
  const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * spread));
  // Push a smallest value toward the end and a largest value toward the front, the costly arrangement.
  if (rand() < 0.7) {
    const low = Math.min(...nums);
    const high = Math.max(...nums);
    nums[n - 1 - Math.floor(rand() * 20)] = low;
    nums[Math.floor(rand() * 20)] = high;
  }
  return [nums];
}
